contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We supply the inputs that C.transfer accepts. We cannot observe the internals of caddress,
    // but we can detect whether C.transfer reverted by try/catch when calling it.
    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        require(_tos.length >= 0);

        bool reverted;
        bool returnedTrue = false;
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            returnedTrue = r;
        } catch {
            reverted = true;
        }

        // General rule: C.transfer only returns true (i.e., not reverted and returnedTrue==true)
        // when the input _tos array is non-empty. Conversely, if _tos is empty it must revert.
        // We express that equivalently: (not reverted && returnedTrue) implies (_tos.length > 0),
        // and (_tos.length == 0) implies reverted.
        assert(((!reverted && returnedTrue) ? (_tos.length > 0) : true) && ((_tos.length == 0) ? reverted : true));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function driving c.transfer and asserting a general property.
    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        // No restrictive preconditions other than allowing any _tos length
        bool didRevert;
        bool ret;
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            didRevert = false;
            ret = r;
        } catch {
            didRevert = true;
            ret = false;
        }

        // General rule: if the call did not revert, it must have returned true AND the _tos array must be non-empty.
        assert(didRevert || (ret && _tos.length > 0));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function: take inputs and call c.transfer exactly once
    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        // allow any inputs but restrict to avoid extremely large loops in analysis
        require(_tos.length <= 5);

        bool didRevert;
        bool ret;
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            didRevert = false;
            ret = r;
        } catch {
            didRevert = true;
            ret = false;
        }

        // General invariant: if it didn't revert then it must have returned true and _tos non-empty
        assert(didRevert || (ret && _tos.length > 0));
    }

    receive() external payable {}
}
